INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"name": "铁铉", "aliases": ["鐵鉉"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文2年（年号对照1400年）十二月，铁铉获任兵部尚书，督理军务。", "biography": null, "status": "draft", "id": "c762b1dc-9ad1-5d54-95f1-1a34c8da3202"}, {"name": "盛庸", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明初将领。本纪记其为都督，参与守卫济南。", "biography": null, "status": "draft", "id": "30198cca-1b25-5099-9bd8-021538a90b39"}, {"name": "朱允炆", "aliases": ["明惠帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明惠帝。洪武31年（年号对照1398年），本表记录了朱允炆的活动。", "biography": null, "status": "draft", "id": "76ea9485-acac-508c-a6ae-e2532462c03e"}, {"name": "李景隆", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "曹国公。本纪记其在建文元年继耿炳文后为征虏大将军。", "biography": null, "status": "draft", "id": "74bfbb9a-13ef-5b0a-8ce8-2e9f902907af"}, {"name": "齐泰", "aliases": ["齊泰"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪武31年（年号对照1398年）五月，齐泰出任兵部尚书，参与处理国家政务。", "biography": null, "status": "draft", "id": "6ffd1a4d-05e3-5c22-a9b8-c44a7ea23c0e"}, {"name": "朱标", "aliases": ["朱標"], "era": "明", "birth_year": null, "death_year": null, "description": "明太祖时的皇太子。本纪记其于洪武二十五年去世。", "biography": null, "status": "draft", "id": "5c5e855f-d901-54a9-80ba-9dfe24f7c9f9"}, {"name": "茹瑺", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪武23年（年号对照1390年）十一月，茹瑺试任兵部尚书。", "biography": null, "status": "draft", "id": "3fd1bde0-0e8f-556a-8f51-766ba44030f2"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "燕军由馆陶渡河", "description": "本纪记燕军于正月乙未由馆陶渡河。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年正月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1217fbc9-d4c8-5800-bde9-69bc9703c892"}, {"title": "燕军逼近徐州", "description": "本纪记载燕军于正月癸丑逼近徐州。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年正月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "73129afc-17d5-5e3e-a736-f4ecee1af828"}, {"title": "宿州失守前平安在淝河作战失利", "description": "燕军攻打宿州。平安追到淝河，杀死燕将王真后遇伏战败，宿州随后失守。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "042da009-7f8d-53fa-8412-e515f639375f"}, {"title": "谭清在大店被围，朱棣率军解围", "description": "朱棣派谭清断徐州运粮道路。谭清回到大店时被铁铉所部包围，朱棣率军救援，谭清突围后与援军合击对方。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年三月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0ec5b963-00ca-5acd-99b8-cb112e4f7264"}, {"title": "何福平安在小河击败燕军", "description": "何福和平安在小河击败燕军，燕将陈文在战事中被杀。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年四月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5520b4f9-8066-5814-b30b-d9325f98ca7b"}, {"title": "徐辉祖等人在齐眉山击败燕军", "description": "徐辉祖等人在齐眉山击败燕军，燕将李斌被杀。燕军惧怕，谋划北撤。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年四月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "65013ddc-287f-5e26-ad39-5f16afa6295e"}, {"title": "何福等驻灵璧，燕军拦截运粮队伍", "description": "何福等人驻于灵璧。燕军拦阻朝廷军队运粮，本纪称平安分出六万人保护运粮队伍。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年四月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a43fec82-148a-5af5-a4a4-1fc97e0fb67f"}, {"title": "朝廷军队在灵璧战败，多名将领官员被俘", "description": "朝廷将领在灵璧与燕军大战，军队失利，陈晖、平安、礼部侍郎陈性善和大理寺卿彭与明均被俘。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年四月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c699831a-03db-57ac-bd5f-24af46440ad4"}, {"title": "燕军攻下泗州，朱棣拜谒祖陵", "description": "燕军攻下泗州，朱棣拜谒祖陵，赐给当地父老牛和酒。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "114a8482-6db4-5c2c-9272-f754bc714e51"}, {"title": "盛庸军在淮上溃散，燕军渡淮进向扬州", "description": "盛庸所部在淮水一带溃散，燕军渡过淮水赶往扬州。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5227fe96-fd06-5a18-b928-08da54757de8"}, {"title": "燕军将领议定转向扬州", "description": "朱棣召集将领议论进军方向。本纪记他提出乘胜直奔扬州并在大江北岸进军，各将赞同。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e0c5abb0-c8c8-5d1d-b44b-bd41ae25c7c5"}, {"title": "燕军进驻扬州一带的大江北岸", "description": "燕军进兵扬州，并在大江北岸驻扎。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ec7c36b2-7783-567b-8237-1b6b77c39b47"}, {"title": "明廷派庆成郡主赴燕军议和", "description": "朝廷派庆成郡主到燕军商谈割地停兵。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年五月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b62bc2aa-9b71-581f-9bd8-803cf2d7873d"}, {"title": "陈瑄率水军归附燕军", "description": "都督佥事陈瑄率水军转而归附燕军。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2d22496f-4730-5354-b331-ea69ff447abb"}, {"title": "燕军祭祀大江", "description": "本纪记燕军于六月甲寅祭大江。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7355fcb4-4449-5372-8c79-613f278987e6"}, {"title": "燕军渡江，盛庸在高资港战败", "description": "燕军渡江。盛庸在高资港迎战，所部战败。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3e9d5bbc-1028-581d-ae46-3d93aeb8a610"}, {"title": "镇江守将童俊归附燕军", "description": "镇江守将童俊转而归附燕军。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f3423384-7495-575d-97b2-d4bbf8c89589"}, {"title": "燕军到达龙潭", "description": "本纪记载，燕军于六月庚申到达龙潭。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d087d2ee-64bc-524e-b9aa-2909960b95ba"}, {"title": "明廷命诸王守都城并派李景隆等继续交涉", "description": "朝廷命诸王分守都城，派李景隆、兵部尚书茹瑺和都督王佐到燕军重提原先议和条件。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "72459365-fb3b-5885-9beb-5f1eed9436c1"}, {"title": "燕军进入金川门，都城失守", "description": "燕军进逼金川门。左都督徐增寿谋划内应，被处死。谷王朱橞和李景隆转而接纳燕军入城，都城失守。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e1235ee2-01af-5534-b9ad-5e187b9fd796"}, {"title": "朱棣命诸将守城并安抚军民", "description": "同一天，朱棣分别命各将守卫都城和皇城，自己返回龙江驻扎，下令安抚军民。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ccd2c880-93d5-520f-9db9-fab2f35fbda2"}, {"title": "燕方搜捕齐泰黄子澄方孝孺等人", "description": "燕方大举搜捕齐泰、黄子澄和方孝孺等五十余人，将其姓名公告为奸臣。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1d4a1ace-04f0-5a73-9b82-9ba7384d5294"}, {"title": "诸王群臣上表请朱棣即位", "description": "诸王和群臣上表，请朱棣即皇帝位。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e2d9708a-b0e7-5696-892b-b7fbaca9909a"}, {"title": "朱棣即皇帝位", "description": "建文四年（1402年），燕王朱棣即皇帝位。宰辅年表在秋七月栏记载此事，成祖本纪则系于六月；月份异文分别保留，不换算公历月日。", "start_year": 1402, "end_year": 1402, "time_original": "建文4年（1402年）", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "6c2cfd4f-f13c-5413-90ec-36695aa4cea3"}, {"title": "明廷恢复周王朱橚和齐王朱榑的王爵", "description": "本纪记朱棣即位后恢复周王朱橚和齐王朱榑的王爵。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0113528d-6271-5a33-91f5-44e04e3538f2"}, {"title": "本纪记燕王遣使取尸并安葬", "description": "本纪载燕王派中使从火中取出其所称帝后尸体，随后在壬申日安葬。卷内也记建文帝的下落不明。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6a36a70-9104-550d-908d-76522840bdf5"}, {"title": "齐泰殉难身亡", "description": "建文4年（年号对照1402年）六月，齐泰殉难身亡。", "start_year": 1402, "end_year": 1402, "time_original": "建文4年（年号对照1402年）六月；公元年核为1402年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "daa0df26-3d94-5fe6-bd31-d2085dc05274"}, {"title": "明廷将朱标神主迁于陵园并恢复称懿文太子", "description": "朝廷把兴宗孝康皇帝朱标的神主迁到陵园，恢复原先的懿文太子称号。", "start_year": 1402, "end_year": 1402, "time_original": "建文四年六月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8032243b-585f-50e9-a898-24e2902a999d"}, {"title": "明廷在南郊祭祀天地并奉太祖配享", "description": "七月初一，明廷在南郊祭祀天地，奉明太祖配享。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年七月壬午朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fe1d18d8-42eb-572f-9b33-74ac1808c2d0"}, {"title": "朱棣改用洪武三十五年并定次年为永乐元年", "description": "朱棣下诏，本年改称洪武三十五年，次年为永乐元年，并恢复建文年间改动的旧制度。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e891fad8-9eb2-551b-ad32-884915e62325"}, {"title": "明廷按地区减免徭役和田租", "description": "朝廷下诏，山东、北平和河南受战事影响州县免徭役三年。未受兵事的地方及凤阳、淮安、徐、滁、扬免田租一年，其他州县免当年一半田租。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7c1f46ca-0ba3-5131-8664-2a22b6df21e6"}, {"title": "明廷任陈瑛为左副都御史并恢复部分官员职务", "description": "朝廷召前北平按察使陈瑛任左副都御史，并恢复建文朝曾被废黜官员的官职。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年七月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c36948b0-c2b9-5e8c-8ca1-6c7a9618b630"}, {"title": "明廷恢复旧官制", "description": "本纪记载，朝廷于七月甲申恢复旧官制。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年七月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3c8cf7f9-ca2b-5284-934f-5abaed07d655"}, {"title": "明廷改封吴王衡王徐王并令居陵园", "description": "朝廷将吳王朱允熥改封广泽王、衡王朱允熞改封怀恩王、徐王本纪作允𤐤，改封敷惠王。三王随母妃吕氏居住在懿文太子陵园。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年七月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1dc3b905-eb81-5abe-ae03-0633135c56cd"}, {"title": "吴高督理河南陕西军备", "description": "江阴侯吴高督理河南、陕西军备，并安抚军民。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年七月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5af46458-6b50-5ff1-80bf-5f2be381438b"}, {"title": "严震直与已经退休的户部尚书王钝一同巡视中原", "description": "建文4年（年号对照1402年）七月，严震直与已经退休的户部尚书王钝一同巡视中原。", "start_year": 1402, "end_year": 1402, "time_original": "建文4年（年号对照1402年）七月；公元年核为1402年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "7f2da66a-6be6-5b35-b61a-915bd2b49d72"}, {"title": "朱棣开始选派翰林官入直文渊阁", "description": "建文四年（1402年），朱棣开始选派翰林官入直文渊阁。原表同时记载仍沿用洪武三十五年的年次。", "start_year": 1402, "end_year": 1402, "time_original": "建文4年（1402年）", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "f1cd4e2d-a06b-5e83-b1cc-2146835b97c0"}, {"title": "解缙以翰林侍读身份入直文渊阁", "description": "建文4年（1402年）八月，解缙以翰林侍读身份入直文渊阁。", "start_year": 1402, "end_year": 1402, "time_original": "建文4年（1402年）八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "9c59db31-535d-5ee6-82db-f6a9515b4ded"}, {"title": "黄淮以翰林编修身份入直文渊阁", "description": "建文4年（1402年）八月，黄淮以翰林编修身份入直文渊阁。", "start_year": 1402, "end_year": 1402, "time_original": "建文4年（1402年）八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "35623ac5-1103-5534-87db-d6e7be87744a"}, {"title": "胡广以翰林侍讲身份入直文渊阁", "description": "建文4年（1402年）九月，胡广以翰林侍讲身份入直文渊阁。", "start_year": 1402, "end_year": 1402, "time_original": "建文4年（1402年）九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "45622bd2-8ace-5fa6-bcce-97b994520dc5"}, {"title": "铁铉遇难身亡", "description": "建文4年（年号对照1402年）八月，铁铉遇难身亡。", "start_year": 1402, "end_year": 1402, "time_original": "建文4年（年号对照1402年）八月；公元年核为1402年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "74664192-823d-505b-9cc1-69a8c721071a"}, {"title": "刘真镇守辽东", "description": "左军都督刘真镇守辽东。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2310e75a-9eab-577b-b27e-7ababc99f5fd"}, {"title": "明廷分派御史察访各地利弊", "description": "朝廷分派御史到各地察访利弊。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年八月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5b9e2186-2aa4-533e-a454-835d303a33a5"}, {"title": "何福镇守宁夏，韩观在江西练兵", "description": "何福任征虏将军，镇守宁夏，节制陕西行都司。韩观在江西训练军队，并节制广东、福建。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年八月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "70e3eff1-6929-55a8-b79a-dcfb5cdf3434"}, {"title": "沐晟镇守云南", "description": "西平侯沐晟镇守云南。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年八月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "530a5d78-e182-59b9-9a57-3f93d040f347"}, {"title": "明廷按靖难功劳封赏丘福朱能等", "description": "朝廷评定靖难功劳，封丘福为淇国公、朱能为成国公，张武等十三人为侯，徐祥等十一人为伯。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年九月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d5dc506c-6e82-5d86-96c9-fe362d377430"}, {"title": "茹瑺获封忠诚伯，仍留任原职", "description": "建文4年（年号对照1402年）九月，茹瑺获封忠诚伯，仍留任原职。", "start_year": 1402, "end_year": 1402, "time_original": "建文4年（年号对照1402年）九月；公元年核为1402年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "914f6f07-5d58-5f65-aafa-a8f6c969bf68"}, {"title": "明廷定功臣犯死罪减俸规例", "description": "朝廷制定功臣犯死罪后减俸的规例。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年九月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "41ac475d-c261-5bd7-be42-7b98556c4da2"}, {"title": "明廷迁山西无田民户到北平", "description": "朝廷把山西无田民户迁往北平，发给宝钞，免役五年。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年九月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8611fd50-460f-5fd9-8e1a-47ddc00e6e32"}, {"title": "韩观担任征南将军镇广西", "description": "朝廷任命韩观为征南将军，镇守广西。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "00c49945-0ff7-5c43-8727-777f9c4b7049"}, {"title": "明廷准朱宁等交粮免死并戍兴州", "description": "朝廷准许北平各州县弃官避兵的朱宁等二百一十九人缴粮免死，发往兴州戍守。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年十月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f69fa298-a2c4-55c1-9165-f1059d96ad98"}, {"title": "明廷修撰《太祖实录》", "description": "本纪记载，新朝于十月己未开展修撰《太祖实录》。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年十月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cf61ba06-f36b-5842-a239-eb21caeb0845"}, {"title": "顾成镇守贵州", "description": "镇远侯顾成镇守贵州。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年十月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ca39e150-4eff-5ecd-a569-74e57cbcc872"}, {"title": "谷王朱橞改驻长沙", "description": "朝廷将谷王朱橞的封地迁往长沙。校记据月朔顺序及实录核定为壬申。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年十月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0835b04b-077d-5e4f-96c4-1b6a13440b94"}, {"title": "明廷命从征将士送还遭掳的子女", "description": "朝廷下诏，从征将士掳走民间子女的，须将其送还原来家庭。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年十月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b60d38c0-504d-5c80-92b5-f2bca2061039"}, {"title": "朱棣立徐氏为皇后", "description": "朱棣册立妃徐氏为皇后。", "start_year": 1402, "end_year": 1402, "time_original": "洪武三十五年十一月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "effaed6c-e1dd-5dc4-a427-5b1828bd9d0a"}, {"title": "广泽王与怀恩王被废为庶人", "description": "朝廷废广泽王朱允熥和怀恩王朱允熞为庶人。 按原历纪年，事情发生在公元1402至1403年之间。", "start_year": null, "end_year": null, "time_original": "洪武三十五年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e9fac150-d8fc-52b8-a057-afb7c3c8c23c"}, {"title": "明廷免征受战事影响州县次年夏税", "description": "朝廷下令，受本次战事影响的州县免征次年夏税。", "start_year": 1403, "end_year": 1403, "time_original": "洪武三十五年十二月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8e12aa49-b19c-5126-aea3-280a912254b4"}]'::jsonb)
