INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "本纪记燕军于正月乙未由馆陶渡河。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000972；建文四年正月乙未", "note": "原文：乙未，由館陶渡河。；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "5ac7c24f-7273-5462-aa19-92697072554e", "subject_id": "1217fbc9-d4c8-5800-bde9-69bc9703c892", "source_id": "3a4ecb68-2341-5377-92cd-becb0f950a3b"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历建文四年正月乙未。DDBC历表换算所据为1402-02-22至1402-02-22，据此核对公元发生年份。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000972；建文四年正月乙未", "note": "原文：乙未，由館陶渡河。；核对说明：原历纪年按本段及相邻年条核对，史料未载的具体日保留为空。", "status": "draft", "id": "5a72fde8-b2aa-5f13-bb11-9f175fc6c444", "subject_id": "1217fbc9-d4c8-5800-bde9-69bc9703c892", "source_id": "3a4ecb68-2341-5377-92cd-becb0f950a3b"}, {"subject_table": "event", "field_path": "description", "claim_text": "《成祖本纪》记燕军于正月癸丑进兵趋向徐州。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000972；建文四年正月癸丑", "note": "原文：癸丑，徇徐州。；核对说明：同一行动的跨卷记载采用稳定事件编号，新引文保存《成祖本纪》的视角与日期。", "status": "draft", "id": "29aea6d1-65cd-5f34-816e-db303e6f87b1", "subject_id": "73129afc-17d5-5e3e-a736-f4ecee1af828", "source_id": "3a4ecb68-2341-5377-92cd-becb0f950a3b"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历建文四年正月癸丑。DDBC历表换算所据为1402-03-12至1402-03-12，据此核对公元发生年份。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000972；建文四年正月癸丑", "note": "原文：癸丑，徇徐州。；核对说明：同一行动的跨卷记载采用稳定事件编号，新引文保存《成祖本纪》的视角与日期。", "status": "draft", "id": "6e1bc8df-f2bb-51c7-a660-630d29e7b418", "subject_id": "73129afc-17d5-5e3e-a736-f4ecee1af828", "source_id": "3a4ecb68-2341-5377-92cd-becb0f950a3b"}, {"subject_table": "person", "field_path": "description", "claim_text": "朱棣率部在淝河击败平安。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000973；建文四年三月壬辰", "note": "原文：壬辰，平安以四萬騎躡王軍，王設伏淝河，大敗之。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "ec776ca3-7033-54a2-919e-01ef95961e53", "subject_id": "dd806a37-77e8-5244-96e9-4d71db81b600", "source_id": "86448442-190d-573c-b2c5-5a3586a2b727"}, {"subject_table": "event", "field_path": "description", "claim_text": "本纪记平安率四万骑兵追击燕军，朱棣在淝河设伏并击败对方。兵数按本纪所载。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000973；建文四年三月壬辰", "note": "原文：壬辰，平安以四萬騎躡王軍，王設伏淝河，大敗之。；核对说明：同一行动的跨卷记载采用稳定事件编号，新引文保存《成祖本纪》的视角与日期。", "status": "draft", "id": "e6e2aebb-cdc5-592b-9034-923262081805", "subject_id": "042da009-7f8d-53fa-8412-e515f639375f", "source_id": "86448442-190d-573c-b2c5-5a3586a2b727"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历建文四年三月壬辰。DDBC历表换算所据为1402-04-20至1402-04-20，据此核对公元发生年份。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000973；建文四年三月壬辰", "note": "原文：壬辰，平安以四萬騎躡王軍，王設伏淝河，大敗之。；核对说明：同一行动的跨卷记载采用稳定事件编号，新引文保存《成祖本纪》的视角与日期。", "status": "draft", "id": "4e629add-1e76-56ac-9d7f-5403bbf20cdd", "subject_id": "042da009-7f8d-53fa-8412-e515f639375f", "source_id": "86448442-190d-573c-b2c5-5a3586a2b727"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "率部在淝河击败平安", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000973；建文四年三月壬辰", "note": "原文：壬辰，平安以四萬騎躡王軍，王設伏淝河，大敗之。；核对说明：只采用本段明确参与者和行动角色，既有连接按稳定编号复用。", "status": "draft", "id": "f4dc3c43-2c8e-57ed-8dc2-311cddd14e82", "subject_id": "0749d6dc-364b-5610-baed-575031511fb2", "source_id": "86448442-190d-573c-b2c5-5a3586a2b727"}, {"subject_table": "person", "field_path": "description", "claim_text": "铁铉所部在大店围困谭清。", "citation": "《明史》卷5·本纪第五·成祖一·mingshi-2f603db3d81e-p000973；建文四年三月丙午", "note": "原文：丙午，遣譚清斷徐州餉道，還至大店，為鐵鉉軍所圍。王引兵馳援，清突圍出，合擊敗之。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "a647b258-a134-5f09-8e76-7ce99c0ff608", "subject_id": "c762b1dc-9ad1-5d54-95f1-1a34c8da3202", "source_id": "86448442-190d-573c-b2c5-5a3586a2b727"}, {"subject_table": "event", "field_path": "description", "claim_text": "朱棣派谭清